svg.script:
const NS='http://www.w3.org/2000/svg';
const WASM_B64='';
const MODULES=[
{id:'reader',title:'READER + IVM-13',version:'v0.1',eng:['I13'],status:'8/8 reader · 9/9 IVM',body:['lowercase i = ingress/toolchain role','reads source without inventing language syntax']},
{id:'norm',title:'NORMALIZER + VALIDATOR',version:'v0.2',eng:['I13'],status:'12/12 normalizer',body:['provenance-complete canonical handoff','15-opcode VM · net = binds - k · no br']},
{id:'python',title:'PYTHON INGRESS + ROUNDTRIP',version:'v0.1',eng:['PY','I13'],status:'10/10 ingress · 12/12 roundtrip',body:['CPython AST enters I-13 through an adapter','unsupported syntax is preserved, not guessed']},
{id:'jit',title:'JIT SHELL',version:'v0.2',eng:['PY','I13'],status:'7/7',body:['capability-addressed execution shell','safe numeric builtins + deterministic cache']},
{id:'wasm1',title:'BROWSER-NATIVE WASM',version:'v0.1',eng:['WASM','I13'],status:'14/14 combined',body:['Cortex gates move into WebAssembly','Python remains attached capability, not trust root']},
{id:'wasm2',title:'WASM VALIDATOR + NUMERIC VM',version:'v0.2',eng:['WASM'],status:'9/9',body:['numeric VM + validation inside Wasm','separate validation regions start at h = 0']},
{id:'gfx',title:'GFX TRUNK',version:'v0.3 → v0.4.1',eng:['WASM','GPU'],status:'16/16 v0.3 · 8/8 native GFX',body:['Wasm emits compact graphics command records','WebGPU primary · WebGL2 fallback · mouse manipulation']},
{id:'child',title:'CORTEX CHILD',version:'H1.0 frozen',eng:['CORTEX'],status:'bounded',body:['[c[(...)]] = ephemeral Cortex child','SPAWN → RUN → RETURN → WITNESS → TERMINATE → 0']},
{id:'pulse',title:'PULSE',version:'v0.1 experimental',eng:['PY','WASM'],status:'reference engine embedded',body:['... = hard pulse boundary','120 + 10 = 130 > 128; × 2 = 260']},
{id:'vh1',title:'VH1 TERNARY / HAMILTONIAN',version:'frozen',eng:['WASM','LA'],status:'10/10 reference',body:['base 3 · depth 0..4 · width 1,3,9,27,81','factored Hermitian operators; not physical quantum hardware']},
{id:'vh2',title:'VH2 CUBI',version:'hypothesis test',eng:['QEC'],status:'10/10 numerical',body:['[[5,1,3]] reference · 5 physical → 1 logical','control topology 5 → (2 internal | 3 external) → 1']},
{id:'freeze',title:'H1.0 FINAL',version:'frozen',eng:['FREEZE'],status:'immutable baseline',body:['H1.1 changes do not overwrite H1.0','odd width: N=2k+1 → k | k+1 → 1']},
{id:'corpus',title:'H1.1 TECHNICAL CORPUS',version:'seed',eng:['CORPUS'],status:'54 records',body:['ternary · linear algebra · Ada/Babbage · DOS','vector · voxel · vogel · VS · Sonia/Kovalevskaya']},
{id:'ology',title:'OLOGY → VOXEL → CV',version:'CURRENT',eng:['WASM','CORTEX'],status:'live below',body:['32-bit 2D surface: x:16 | y:16','each vector roots local voxel; c[v[(),{},()]]cv']}
];
function el(name,attrs={},text=''){const n=document.createElementNS(NS,name);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);if(text)n.textContent=text;return n}
function drawModules(){const layer=document.getElementById('module-layer'),y0=545,dy=123;MODULES.forEach((m,i)=>{const y=y0+i*dy,g=el('g',{'data-module':m.id});g.append(el('circle',{cx:92,cy:y+39,r:9,class:'node'}));g.append(el('line',{x1:101,y1:y+39,x2:140,y2:y+39,class:'soft'}));g.append(el('rect',{x:140,y,width:1070,height:92,rx:7,class:'box'}));g.append(el('text',{x:160,y:y+27,class:'module-title'},m.title));g.append(el('text',{x:160,y:y+51,class:'small muted'},m.version+' · '+m.status));g.append(el('text',{x:160,y:y+73,class:'small'},m.body[0]));g.append(el('text',{x:620,y:y+73,class:'small'},m.body[1]));let tx=1125;[...m.eng].reverse().forEach(tag=>{const w=Math.max(52,tag.length*9+18);tx-=w;g.append(el('rect',{x:tx,y:y+13,width:w,height:25,rx:12,class:'tag'}));g.append(el('text',{x:tx+w/2,y:y+31,'text-anchor':'middle',class:'tiny'},tag));tx-=7});layer.append(g)})}
let wasm=null,py=null,state={x:0xc0a8,y:0x012a,depth:0,authority:true,maxDepth:81};
function bytesFromB64(s){const raw=atob(s),a=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)a[i]=raw.charCodeAt(i);return a}
async function bootWasm(){try{const r=await WebAssembly.instantiate(bytesFromB64(WASM_B64),{});wasm=r.instance.exports;const ok=wasm.i13_x(wasm.i13_pack(192,168))===192&&wasm.i13_y(wasm.i13_pack(192,168))===168&&wasm.i13_width3(4)===81&&wasm.i13_pulse(120,10,2)===260;document.getElementById('runtime').textContent='WASM: '+(ok?'PASS · embedded 429 B':'FAIL');render()}catch(e){document.getElementById('runtime').textContent='WASM: FAIL '+e.message}}
function packed(){return wasm?wasm.i13_pack(state.x,state.y):(((state.x&65535)<<16)|(state.y&65535))>>>0}function ipv4(a){return[a>>>24,(a>>>16)&255,(a>>>8)&255,a&255].join('.')}
function render(){const a=packed()>>>0;document.getElementById('addr').textContent=`<${state.x},${state.y}> · u32 0x${a.toString(16).padStart(8,'0')}`;document.getElementById('ipv4').textContent='same 32 bits as IPv4 view: '+ipv4(a);document.getElementById('depth-label').textContent='local voxel depth '+state.depth+' / '+state.maxDepth;document.getElementById('authority-text').textContent='AUTHORITY '+(state.authority?'ON':'OFF');const q=document.getElementById('queen'),ql=document.getElementById('queen-label'),sx=340+((state.y%11)-5)*34,sy=230-((state.x%9)-4)*34;q.setAttribute('cx',sx);q.setAttribute('cy',sy);ql.setAttribute('x',sx+15);ql.setAttribute('y',sy-4);document.getElementById('depth-dot').setAttribute('cy',142+Math.min(4,state.depth/Math.max(1,state.maxDepth)*4)*43)}
function grid(){const g=document.getElementById('grid-lines');for(let i=-7;i<=7;i++)g.append(el('line',{x1:340+i*34,y1:80,x2:340+i*34,y2:375,class:'soft'}));for(let i=-4;i<=4;i++)g.append(el('line',{x1:85,y1:230+i*34,x2:600,y2:230+i*34,class:'soft'}))}
function move(dir){if(!wasm)return;const map={up:0,down:1,right:2,left:3},r=wasm.i13_step(packed(),map[dir]);if(r===0n)return;const a=Number(r&0xffffffffn)>>>0;state.x=wasm.i13_x(a);state.y=wasm.i13_y(a);document.getElementById('cv-label').textContent='cv: surface move proposed/committed';render()}
function verify(){const v=wasm?wasm.i13_cv(state.authority?1:0,0,state.depth,state.maxDepth):0;document.getElementById('cv-label').textContent='cv: '+(v?'PASS · enable exit':'VETO · hold/return')}
async function pyEngine(){const out=document.getElementById('py-runtime');try{out.textContent='PY: loading Pyodide 314.0.4…';if(!py){const mod=await import('https://cdn.jsdelivr.net/pyodide/v314.0.4/full/pyodide.mjs');py=await mod.loadPyodide({indexURL:'https://cdn.jsdelivr.net/pyodide/v314.0.4/full/'})}const result=py.runPython(`import ast\n\ndef execute_pulse_transition(state_vector, threshold_boundary, verification_witness):\n    adjusted_vector = state_vector + threshold_boundary\n    if adjusted_vector > 128:\n        return adjusted_vector * verification_witness\n    return None\n\ntree=ast.parse('x = 1 + 2')\n(nodes := [type(n).__name__ for n in ast.walk(tree)]), execute_pulse_transition(120,10,2)`);out.textContent='PY: PASS · AST + pulse → '+result.toString().slice(0,54)}catch(e){out.textContent='PY: unavailable · '+e.message}}
function wire(){document.querySelectorAll('[data-act]').forEach(n=>n.addEventListener('click',()=>{const a=n.getAttribute('data-act');if(['up','down','left','right'].includes(a))move(a);else if(a==='burrow+'){state.depth=Math.min(0xffffffff,state.depth+1);render()}else if(a==='burrow-'){state.depth=Math.max(0,state.depth-1);render()}else if(a==='authority'){state.authority=!state.authority;render()}else if(a==='verify')verify();else if(a==='wasmtest')bootWasm();else if(a==='pytest')pyEngine()}))}
drawModules();grid();wire();render();bootWasm();
